+import React from "react";
+import classNames from "classnames";
+
+import { aboveLeftOf, ChevronFace, useContextMenu } from "../../structures/ContextMenu";
+import { ContextMenuButton } from "../../../accessibility/context_menu/ContextMenuButton";
+import IconizedContextMenu, { IconizedContextMenuOptionList } from "./IconizedContextMenu";
+
+interface IProps extends Omit<
+    React.ComponentProps<typeof ContextMenuButton>, "children" | "label" | "isExpanded" | "onClick"
+> {
+    options: React.ReactNode[];
+    title: string;
+}
+
+export const KebabContextMenu: React.FC<IProps> = ({ options, title, disabled, className, ...buttonProps }) => {
+    const [isMenuOpen, buttonRef, openMenu, closeMenu, setMenuOpen] = useContextMenu<HTMLDivElement>();
+
+    React.useEffect(() => {
+        if (disabled) {
+            setMenuOpen(false);
+        }
+    }, [disabled, setMenuOpen]);
+
+    const preventDisabledContextMenu = (ev: React.MouseEvent) => {
+        ev.preventDefault();
+        ev.stopPropagation();
+    };
+
+    const onTriggerClick = (ev: React.SyntheticEvent) => {
+        buttonRef.current?.focus();
+        openMenu(ev);
+    };
+
+    let menu: JSX.Element | null = null;
+    if (isMenuOpen && buttonRef.current) {
+        const buttonRect = buttonRef.current.getBoundingClientRect();
+        const position = aboveLeftOf(buttonRect, ChevronFace.None, 4);
+        // Keep this menu below its trigger while the wrapper style aligns its right edge.
+        position.top = buttonRect.bottom + window.scrollY + 4;
+        position.bottom = undefined;
+
+        menu = <IconizedContextMenu
+            {...position}
+            onFinished={closeMenu}
+            wrapperClassName="mx_KebabContextMenu_menu"
+        >
+            <IconizedContextMenuOptionList red>
+                { options }
+            </IconizedContextMenuOptionList>
+        </IconizedContextMenu>;
+    }
+
+    return <>
+        <ContextMenuButton
+            {...buttonProps}
+            className={classNames("mx_KebabContextMenu_trigger", className, {
+                mx_KebabContextMenu_trigger_open: isMenuOpen,
+            })}
+            inputRef={buttonRef}
+            label={title}
+            isExpanded={isMenuOpen}
+            disabled={disabled}
+            aria-disabled={disabled}
+            onClick={onTriggerClick}
+            onContextMenu={disabled ? preventDisabledContextMenu : buttonProps.onContextMenu}
+        >
+            <span className="mx_KebabContextMenu_icon" aria-hidden="true" />
+        </ContextMenuButton>
+        { menu }
+    </>;
+};
+
+export default KebabContextMenu;
